import useAuthUser from "@/hooks/useAuthUser";

import { EncounterClass } from "@/types/emr/encounter/encounter";
import workspaceApi from "@/types/workspace/workspaceApi";
import query from "@/Utils/request/query";

/** Defaults are encounter matching rules; facility scope belongs to the workspace. */
export function useEncounterWorkspaces(
  facilityId: string,
  encounterClass?: EncounterClass,
) {
  const user = useAuthUser();
  const defaults = useQuery({
    queryKey: ["workspace-user-defaults", user.id, "encounter"],
    queryFn: query(workspaceApi.getUserDefaultAttributes, { silent: true }),
    retry: false,
  });
  const matches = defaults.data?.results.filter(
    ({ attribute, value, workspace }) =>
      attribute === "encounter_class" &&
      value === encounterClass &&
      workspace.facility === facilityId &&
      (workspace.auth_context !== "user" || workspace.created_by?.id === user.id),
  ) ?? [];
  const workspaces = [...new Map(matches.map(({ workspace }) => [workspace.id, workspace])).values()];

  return {
    defaults,
    workspace: !defaults.isError && workspaces.length === 1 ? workspaces[0] : undefined,
    hasConflictingDefaults: workspaces.length > 1,
  };
}
